#!/usr/bin/env node
// Builds cloud/src/legal/pages.gen.ts from the six docs/legal/{terms,privacy,refund}{,.ko}.md files (the only source;
// the generated file is not committed). `--strict` (predeploy) refuses any draft mark left — every `{{…}}`, any
// unpaired `{{`/`}}` and the DRAFT banner — and lists each with its file and line, so drafts can never be deployed.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { LegalSyntaxError, renderLegal } from './legal-md.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const docsDir = join(here, '..', '..', 'docs', 'legal');
const outFile = join(here, '..', 'src', 'legal', 'pages.gen.ts');
const strict = process.argv.includes('--strict');

const DOCS = ['terms', 'privacy', 'refund'];
const LANGS = { en: '', ko: '.ko' };
const fileOf = (doc, lang) => `${doc}${LANGS[lang]}.md`;

/** Relative links between the documents → their app-origin paths. */
const links = {};
for (const doc of DOCS) for (const lang of Object.keys(LANGS)) links[fileOf(doc, lang)] = lang === 'en' ? `/legal/${doc}` : `/legal/ko/${doc}`;

const fail = (lines) => { for (const l of lines) console.error(l); process.exit(1); };

const missing = DOCS.flatMap((doc) => Object.keys(LANGS).map((lang) => fileOf(doc, lang))).filter((f) => !existsSync(join(docsDir, f)));
if (missing.length) fail(missing.map((f) => `build-legal: missing docs/legal/${f}`));

const legal = {};
const left = [];
let draft = false;
for (const doc of DOCS) {
  legal[doc] = {};
  for (const lang of Object.keys(LANGS)) {
    const f = fileOf(doc, lang);
    let r;
    try {
      r = renderLegal(readFileSync(join(docsDir, f), 'utf8'), { strict: false, links });
    } catch (e) {
      if (e instanceof LegalSyntaxError) fail([`build-legal: docs/legal/${f}:${e.line}: ${e.message}`]);
      throw e;
    }
    if (!r.title) fail([`build-legal: docs/legal/${f}: no # title`]);
    for (const m of r.marks) left.push(`  docs/legal/${f}:${m.line}: ${m.text}`);
    draft ||= r.marks.length > 0;
    legal[doc][lang] = { title: r.title, html: r.html };
  }
}

if (strict && left.length) {
  const banners = left.filter((l) => l.endsWith(': DRAFT')).length;
  const stray = left.filter((l) => /: unpaired (\{\{|\}\})$/.test(l)).length;
  fail([`build-legal --strict: ${left.length} draft marks left (${left.length - banners - stray} {{…}} placeholders, ${stray} unpaired braces, ${banners} DRAFT banners) — fill them in docs/legal/ before deploying:`, ...left]);
}

mkdirSync(dirname(outFile), { recursive: true });
writeFileSync(outFile, `// Generated by cloud/scripts/build-legal.mjs from docs/legal/*.md. Do not edit; not committed (.gitignore).
export const LEGAL = ${JSON.stringify(legal, null, 2)} as const;
export const LEGAL_DRAFT: boolean = ${draft};
`);
console.log(`build-legal: wrote src/legal/pages.gen.ts${draft ? ` (draft: ${left.length} marks left)` : ''}`);
